//! Direct Newton energy Gram of high-precision loaded full current states.
use pcb_analyze::extraction::local::polyhedron::{PointPotential,TetraCubature,tetra_integral_adaptive,tetra_self_integral};
use serde_json::Value;
fn separated_order(q:f64,maximum:usize)->Option<usize>{let order=if q.is_finite()&&q<0.12{4}else if q<0.6{6}else if q<1.{8}else{return None};(order<=maximum).then_some(order)}
fn main()->Result<(),String>{
 let args:Vec<_>=std::env::args().collect();if args.len()!=5&&args.len()!=6{return Err("d1_direct_loaded_gram <full-prepared.json> <loaded-states.json> <output.json> <order> [channel-plan.json]".into());}
 let input:Value=serde_json::from_slice(&std::fs::read(&args[1]).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;
 let loaded:Value=serde_json::from_slice(&std::fs::read(&args[2]).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;
 let order=args[4].parse::<usize>().map_err(|_|"invalid order")?;if !(8..=16).contains(&order){return Err("order 8..16 required".into());}
 let nodes:Vec<[f64;3]>=serde_json::from_value(input["nodesM"].clone()).map_err(|e|e.to_string())?;let cells:Vec<[usize;4]>=serde_json::from_value(input["copperCells"].clone()).map_err(|e|e.to_string())?;let density:Vec<f64>=serde_json::from_value(input["cellDensityPerAmpM2"].clone()).map_err(|e|e.to_string())?;
 let owners=if args.len()==6{
  let plan:Value=serde_json::from_slice(&std::fs::read(&args[5]).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let origin=input["originMm"][0].as_f64().ok_or("X origin required")?;
  let ranges:Vec<(String,f64,f64)>=plan["blocks"].as_array().ok_or("plan blocks required")?.iter().map(|b|{let xs:Vec<f64>=b["ownership"].as_array().into_iter().flatten().flat_map(|o|o["domainPolygonMm"].as_array().into_iter().flatten()).map(|p|p[0].as_f64().unwrap()).collect();Ok((b["id"].as_str().ok_or("block id required")?.to_string(),xs.iter().copied().fold(f64::INFINITY,f64::min),xs.iter().copied().fold(f64::NEG_INFINITY,f64::max)))}).collect::<Result<_,String>>()?;
  // Diagnostic only: retain the original full tetrahedra and assign each one
  // by its centroid. This avoids singular clipped cells; it is not a regional
  // acceptance certificate for tetrahedra straddling a block boundary.
  cells.iter().map(|cell|{let x=cell.iter().map(|&i|nodes[i][0]*1000.+origin).sum::<f64>()/4.;let matches:Vec<_>=ranges.iter().filter(|(_,lo,hi)|x>=*lo-1e-8&&x<=*hi+1e-8).collect();if matches.len()!=1{return Err(format!("cell centroid does not have exactly one block owner: x={x}, {matches:?}"));}Ok(matches[0].0.clone())}).collect::<Result<Vec<_>,String>>()?
 }else{vec!["all".into();cells.len()]};
 let tetra:Vec<[[f64;3];4]>=cells.iter().map(|c|c.map(|i|nodes[i])).collect();let n=tetra.len();let sources:Vec<_>=tetra.iter().copied().map(PointPotential::tetrahedron).collect::<Result<_,_>>()?;let orders:Vec<_>=[4,6,8,12,16].into_iter().filter(|&v|v<=order).collect();let cubatures:Vec<Vec<_>>=tetra.iter().copied().map(|t|orders.iter().map(|&v|TetraCubature::new(t,v)).collect::<Result<Vec<_>,_>>()).collect::<Result<_,_>>()?;
 let started=std::time::Instant::now();let mut kernel=vec![0.;n*n];for i in 0..n{for j in 0..=i{let value=if i==j{tetra_self_integral(tetra[i],order)?}else{let q=cubatures[i][0].separation_q(&cubatures[j][0]);if let Some(k)=separated_order(q,order).and_then(|v|orders.iter().position(|&candidate|candidate==v)){cubatures[i][k].direct_integral(&cubatures[j][k])?}else{tetra_integral_adaptive(tetra[i],&sources[j],order,1e-12)?}};kernel[i*n+j]=value;kernel[j*n+i]=value;}}
 let states=loaded["states"].as_array().ok_or("loaded states required")?;let mut full=vec![vec![0.;states.len()];states.len()];let mut reduced=full.clone();let mut groups:std::collections::BTreeMap<String,Vec<Vec<f64>>>=std::collections::BTreeMap::new();
 for i in 0..states.len(){for j in 0..=i{for(prefix,gram)in[("full",&mut full),("reduced",&mut reduced)]{
  let ar:Vec<f64>=serde_json::from_value(states[i][format!("{prefix}CurrentReal")].clone()).map_err(|e|e.to_string())?;let ai:Vec<f64>=serde_json::from_value(states[i][format!("{prefix}CurrentImaginary")].clone()).map_err(|e|e.to_string())?;let br:Vec<f64>=serde_json::from_value(states[j][format!("{prefix}CurrentReal")].clone()).map_err(|e|e.to_string())?;let bi:Vec<f64>=serde_json::from_value(states[j][format!("{prefix}CurrentImaginary")].clone()).map_err(|e|e.to_string())?;
  if ar.len()!=3*n||ai.len()!=3*n||br.len()!=3*n||bi.len()!=3*n{return Err("loaded current size mismatch".into());}let mut contraction=0.;for a in 0..n{for b in 0..n{let dot=(0..3).map(|axis|ar[3*a+axis]*br[3*b+axis]+ai[3*a+axis]*bi[3*b+axis]).sum::<f64>();let term=density[a]*density[b]*dot*kernel[a*n+b];contraction+=term;if prefix=="full"{let(x,y)=(&owners[a],&owners[b]);let key=if x==y{format!("self:{x}")}else if x<=y{format!("cross:{x}:{y}")}else{format!("cross:{y}:{x}")};let group=groups.entry(key).or_insert_with(||vec![vec![0.;states.len()];states.len()]);let value=1e-7/2.*term;group[i][j]+=value;if i!=j{group[j][i]+=value;}}}}let value=1e-7/2.*contraction;gram[i][j]=value;gram[j][i]=value;
 }}}
 let result=serde_json::json!({"source":args[1],"loadedStates":args[2],"order":order,"drives":states.iter().map(|s|s["driveA"].clone()).collect::<Vec<_>>(),"owners":owners,"fullDirectGroups":groups,"fullDirectEnergyGram":full,"reducedDirectEnergyGram":reduced,"wallSeconds":started.elapsed().as_secs_f64()});std::fs::write(&args[3],serde_json::to_vec_pretty(&result).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;println!("{}",serde_json::to_string(&result).map_err(|e|e.to_string())?);Ok(())
}
